function parsePaperclipActionBlocks(text) {
    const actions = [];
    const re = /```paperclip\s*\n([\s\S]*?)```/g;
    let m;
    while ((m = re.exec(text)) !== null) {
        try {
            const parsed = JSON.parse(m[1].trim());
            if (parsed && typeof parsed.tool === "string") {
                actions.push({ tool: parsed.tool, args: parsed.args ?? {} });
            }
        }
        catch {
            // Skip malformed blocks; the model sees no result and can retry.
        }
    }
    return actions;
}
